"""DS4 gfx1151: single-kernel MoE routing for tiny decode batches.

Replaces the 5-kernel pack_bitmatrix -> bitmatrix.sum -> memset -> compute
routing pipeline (plus 3 aten prep ops) with ONE triton kernel when
n_rows * topk <= 64 and every expert can need at most one matmul tile
(n_rows <= 16 <= min block_m). Eager decode is dominated by per-launch
Python+dispatch overhead, so the launch-count reduction is the point, not
the GPU time.

Bit-exact contract with triton_kernels.routing.routing_from_bitmatrix
(legacy path) for the consumed outputs:
  hist, token_offs_raw, token_offs_pad[bm][:E+1], block_pid_map[bm][:G],
  topk_indx / gate_indx (invalid gates -1), gate_scal[i] for sorted-valid i.
"""
import torch
import triton
import triton.language as tl

from triton_kernels.routing import (
    ExptData,
    GatherIndx,
    RoutingData,
    ScatterIndx,
)

_PAD = 512  # MEMSET_BLOCK padding of the stock _compute_expt_data_internal
_N_BLOCK_MS = 5  # block_m in (16, 32, 64, 128, 256) on HIP


@triton.jit
def _ds4_tiny_routing_kernel(
    ids_ptr, w_ptr,
    combined_ptr,       # int32 [2*G]: topk_indx | gate_indx
    gate_scal_ptr,      # bf16 [G]
    hist_ptr,           # int32 [E]
    token_offs_ptr,     # int32 [6, PADN] row0 = raw, rows 1..5 = per block_m
    bpm_ptr,            # int32 [5, PADT]
    G, E,
    GP2: tl.constexpr, EP2: tl.constexpr,
    PADN: tl.constexpr, PADT: tl.constexpr,
):
    g_off = tl.arange(0, GP2)
    g_mask = g_off < G
    ids = tl.load(ids_ptr + g_off, mask=g_mask, other=-1).to(tl.int32)
    w = tl.load(w_ptr + g_off, mask=g_mask, other=0.0).to(tl.float32)
    valid = (ids >= 0) & g_mask

    # stable sort by (expert, gate index) via O(G^2) rank counting
    key = tl.where(valid, ids * GP2 + g_off, 2147483647)
    lt = key[None, :] < key[:, None]
    rank = tl.sum(lt.to(tl.int32), axis=1)  # rank among all; invalid sort last

    # topk_indx[i] = gate index with rank i (else -1); gate_scal[i] likewise
    eq = (rank[:, None] == g_off[None, :]) & valid[:, None]
    present = tl.sum(eq.to(tl.int32), axis=0) > 0
    topk_vals = tl.sum(tl.where(eq, g_off[:, None], 0), axis=0)
    topk_vals = tl.where(present, topk_vals, -1)
    scal_vals = tl.sum(tl.where(eq, w[:, None], 0.0), axis=0)
    tl.store(combined_ptr + g_off, topk_vals, mask=g_mask)
    tl.store(gate_scal_ptr + g_off, scal_vals.to(tl.bfloat16),
             mask=g_mask & present)
    # gate_indx[g] = rank of gate g (-1 if invalid)
    tl.store(combined_ptr + G + g_off, tl.where(valid, rank, -1), mask=g_mask)

    # histogram over experts
    er = tl.arange(0, EP2)
    e_mask = er < E
    mat = (ids[None, :] == er[:, None]) & valid[None, :]
    hist = tl.sum(mat.to(tl.int32), axis=1)
    hist = tl.where(e_mask, hist, 0)
    tl.store(hist_ptr + er, hist, mask=e_mask)

    # token_offs_raw: exclusive cumsum of hist, length E+1
    cum = tl.cumsum(hist, axis=0)
    tl.store(token_offs_ptr, 0)
    tl.store(token_offs_ptr + 1 + er, cum, mask=e_mask)

    # per-block_m rows: hist <= n_rows <= 16 <= block_m so cdiv(hist, bm) is
    # (hist > 0) for every block size -> all 5 rows identical
    act = (hist > 0).to(tl.int32)
    cuma = tl.cumsum(act, axis=0)
    for r in tl.static_range(1, 6):
        tl.store(token_offs_ptr + r * PADN, 0)
        tl.store(token_offs_ptr + r * PADN + 1 + er, cuma, mask=e_mask)

    # block_pid_map: tile t -> expert id of t-th active expert (tile 0 only),
    # -1 elsewhere over the full padded row
    pos = cuma - act  # exclusive cumsum: position of each active expert
    eqp = (pos[:, None] == er[None, :]) & (act > 0)[:, None]
    hasv = tl.sum(eqp.to(tl.int32), axis=0) > 0
    vals = tl.sum(tl.where(eqp, er[:, None], 0), axis=0)
    vals = tl.where(hasv, vals, -1)
    pad_off = tl.arange(0, PADT)
    for r in tl.static_range(0, 5):
        tl.store(bpm_ptr + r * PADT + pad_off, -1)
    tl.debug_barrier()
    for r in tl.static_range(0, 5):
        tl.store(bpm_ptr + r * PADT + er, vals, mask=e_mask)


def tiny_routing_supported(n_rows: int, n_expts_act: int, n_expts_tot: int) -> bool:
    return (
        n_rows * n_expts_act <= 64
        and n_rows <= 16
        and n_expts_tot <= 512
    )


_BLOCK_MS = (16, 32, 64, 128, 256)

# (G, E, device_index) -> (buffers..., RoutingData, GatherIndx, ScatterIndx).
# Reuse is safe: every consumer of the previous call's outputs (the two
# matmul_ogs of that layer) is enqueued on the same stream before the next
# routing kernel runs, so in-stream ordering protects the buffers. The cached
# RoutingData is mutated by UnfusedOAITritonExperts.apply (n_expts_act = 1
# before the w2 matmul), so n_expts_act is re-armed on every reuse.
_cache: dict = {}


def make_routing_data_tiny(
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor,
    num_local_experts: int,
):
    """Drop-in replacement for make_routing_data on tiny decode batches."""
    n_rows, n_expts_act = topk_ids.shape
    E = num_local_experts
    G = n_rows * n_expts_act
    device = topk_ids.device

    key = (G, n_expts_act, E, device.index)
    entry = _cache.get(key)
    if entry is None:
        combined = torch.empty(2 * G, dtype=torch.int32, device=device)
        gate_scal = torch.empty(G, dtype=torch.bfloat16, device=device)
        hist = torch.empty(E, dtype=torch.int32, device=device)
        token_offs = torch.empty((_N_BLOCK_MS + 1, _PAD), dtype=torch.int32,
                                 device=device)
        bpm = torch.empty((_N_BLOCK_MS, _PAD), dtype=torch.int32,
                          device=device)
        topk_indx = combined[:G]
        gate_indx = combined[G:]
        token_offs_raw = token_offs[0][: E + 1]
        max_n_tiles = G if G <= E else E - 1 - ((E - G - 1) // 16)
        token_offs_pad = {
            bm: token_offs[i + 1][: E + 1] for i, bm in enumerate(_BLOCK_MS)
        }
        block_pid_map = {
            bm: bpm[i][:max_n_tiles] for i, bm in enumerate(_BLOCK_MS)
        }
        expt_data = ExptData(hist, token_offs_raw, token_offs_pad,
                             block_pid_map)
        routing_data = RoutingData(gate_scal, hist, E, n_expts_act, expt_data)
        gather_indx = GatherIndx(src_indx=topk_indx, dst_indx=gate_indx)
        scatter_indx = ScatterIndx(src_indx=gate_indx, dst_indx=topk_indx)
        entry = (combined, gate_scal, hist, token_offs, bpm,
                 routing_data, gather_indx, scatter_indx)
        _cache[key] = entry
    combined, gate_scal, hist, token_offs, bpm, routing_data, gather_indx, \
        scatter_indx = entry
    # re-arm fields the consumer mutates
    routing_data.n_expts_act = n_expts_act

    _ds4_tiny_routing_kernel[(1,)](
        topk_ids.reshape(-1), topk_weights.reshape(-1),
        combined, gate_scal, hist, token_offs, bpm,
        G, E,
        GP2=max(triton.next_power_of_2(G), 16),
        EP2=triton.next_power_of_2(E),
        PADN=_PAD, PADT=_PAD,
        num_warps=4,
    )
    return routing_data, gather_indx, scatter_indx
